    colors = {3: 8, 5: 4, 7: 3}  # interior side length -> fill color
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in outside or (r,c) in seen:
                continue
            comp = set([(r,c)])
            seen.add((r,c))
            q = deque([(r,c)])
            while q:
